const url = "https://images.example.invalid/banner.png";
if (!/^https:\/\/[a-z0-9-]+(?:\.[a-z0-9-]+)+\//i.test(url) || /[\s\\#]/.test(url))
  throw Error("Use a direct HTTPS image URL without credentials.");
return [{ json: { url } }];

function imageType(bytes, mime) {
  if (bytes.length < 16 || bytes.length > 2097152)
    throw Error("Choose a complete image up to 2 MiB.");
  const png =
    bytes[0] === 137 &&
    bytes.subarray(1, 8).equals(Buffer.from([80, 78, 71, 13, 10, 26, 10])) &&
    bytes.subarray(12, 16).toString("ascii") === "IHDR" &&
    bytes.subarray(-8, -4).toString("ascii") === "IEND";
  const jpeg =
    bytes[0] === 255 &&
    bytes[1] === 216 &&
    bytes[2] === 255 &&
    bytes.at(-2) === 255 &&
    bytes.at(-1) === 217;
  const wanted = png ? "image/png" : jpeg ? "image/jpeg" : "";
  if (!wanted || (mime !== wanted && mime !== "application/octet-stream"))
    throw Error("The response is not a complete PNG or JPEG.");
  return { mimeType: wanted, fileName: png ? "banner.png" : "banner.jpg" };
}
const item = $input.first();
if (item.json.statusCode !== 200) throw Error("The image download was not complete.");
const raw = await helpers.getBinaryDataBuffer(0, "data");
const mime = String(item.binary.data.mimeType ?? "")
  .split(";", 1)[0]
  .toLowerCase();
const properties = imageType(raw, mime);
return [
  {
    json: { imageBytes: raw.length },
    binary: { data: { ...item.binary.data, ...properties } },
    pairedItem: { item: 0 },
  },
];

const reply = $input.first().json;
if (![200, 201, 202].includes(reply.statusCode))
  throw Error("X did not acknowledge the upload. Verify your profile before retrying.");
return [{ json: { status: "accepted", httpStatus: reply.statusCode } }];
